    h,w=len(grid),len(grid[0])
    sr=[i for i,r in enumerate(grid) if len(set(r))==1]
    sc=[j for j in range(w) if len({grid[i][j] for i in range(h)})==1]
    def spans(n,cuts):
        out=[]; s=0
        for k in cuts:
            if k>s: out.append((s,k))
            s=k+1
        if s<n: out.append((s,n))
        return out
    rs,cs=spans(h,sr),spans(w,sc)
    from collections import Counter
    vals=[grid[i][j] for a,b in rs for c,d in cs for i in range(a,b) for j in range(c,d)]
    bg=Counter(vals).most_common(1)[0][0]
    ans=[]
    for a,b in rs:
