    h,w=len(grid),len(grid[0])
    def split(n, sep):
        cuts=[i for i in range(n) if sep(i)]
        spans=[]; s=0
        for k in cuts:
            if s<k: spans.append((s,k))
            s=k+1
        if s<n: spans.append((s,n))
        return spans
    rs=split(h,lambda r:len(set(grid[r]))==1)
    cs=split(w,lambda c:len({grid[r][c] for r in range(h)})==1)
    from collections import Counter
    ans=[]
